// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AttributionRequestClaim) predicate.AttributionRequestClaim {
	return predicate.AttributionRequestClaim(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AttributionRequestClaim) predicate.AttributionRequestClaim {
	return predicate.AttributionRequestClaim(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AttributionRequestClaim) predicate.AttributionRequestClaim {
	return predicate.AttributionRequestClaim(sql.NotPredicates(p))
}
